/// 品牌 logo 渲染（fill 模式）
public struct BrandLogoView: View {
    public let code: String
    public var size: CGFloat = 28

    public init(code: String, size: CGFloat = 28) {
        self.code = code
        self.size = size
    }

    public var body: some View {
        Group {
            if let b64 = BrandIcon.data(code),
               let paths = Self.decode(b64) {
                // 品牌 logo（fill 黑色，白色方块底）
                ZStack {
                    RoundedRectangle(cornerRadius: size * 0.24)
                        .fill(.white)
                        .overlay(
                            RoundedRectangle(cornerRadius: size * 0.24)
                                .stroke(Color.black.opacity(0.08), lineWidth: 1)
                        )
                    BrandPath(paths: paths)
                        .fill(Color.black)
                        .frame(width: size * 0.72, height: size * 0.72)
                }
                .frame(width: size, height: size)
            } else {
                // 兜底：品牌色方块 + 代码缩写
                RoundedRectangle(cornerRadius: size * 0.24)
                    .fill(Color(hex: BrandIcon.brandColor(code) ?? "#666666"))
                    .frame(width: size, height: size)
                    .overlay(
                        Text(Self.abbr(code))
                            .font(.system(size: size * 0.38, weight: .bold, design: .rounded))
                            .foregroundStyle(.white)
                    )
            }
        }
        .frame(width: size, height: size)
    }

    /// 代码缩写（最多 2-3 字符）
    static func abbr(_ code: String) -> String {
        let letters = code.filter { $0.isLetter && $0.isASCII }
        if letters.count >= 3 { return String(letters.prefix(3)).uppercased() }
        if letters.count >= 2 { return String(letters.prefix(2)).uppercased() }
        return String(code.prefix(3)).uppercased()
    }

    /// base64 → [[CGPoint]]
    static func decode(_ b64: String) -> [[CGPoint]]? {
        guard let raw = Data(base64Encoded: b64) else { return nil }
        var floats: [Float] = []
        floats.reserveCapacity(raw.count / 4)
        raw.withUnsafeBytes { buf in
            for i in stride(from: 0, to: buf.count, by: 4) {
                floats.append(buf.loadUnaligned(fromByteOffset: i, as: Float.self))
            }
        }
        var paths: [[CGPoint]] = []
        var cur: [CGPoint] = []
        var pendingX: Float? = nil
        for v in floats {
            if v < 0 {
                if !cur.isEmpty { paths.append(cur); cur = [] }
                pendingX = nil
            } else if let px = pendingX {
                cur.append(CGPoint(x: CGFloat(px), y: CGFloat(v)))
                pendingX = nil
            } else {
                pendingX = v
            }
        }
        if !cur.isEmpty { paths.append(cur) }
        return paths.isEmpty ? nil : paths
    }
}

/// 品牌 path（fill）
public struct BrandPath: Shape {
    public let paths: [[CGPoint]]
    public init(paths: [[CGPoint]]) { self.paths = paths }
    public func path(in rect: CGRect) -> Path {
        var p = Path()
        let scale = min(rect.width / 24.0, rect.height / 24.0)
        let ox = rect.midX - 12 * scale
        let oy = rect.midY - 12 * scale
        for poly in paths {
            guard let first = poly.first else { continue }
            p.move(to: CGPoint(x: first.x * scale + ox, y: first.y * scale + oy))
            for pt in poly.dropFirst() {
                p.addLine(to: CGPoint(x: pt.x * scale + ox, y: pt.y * scale + oy))
            }
            p.closeSubpath()
        }
        return p
    }
}

extension Color {
    /// hex 字符串 → Color
    public init(hex: String) {
        let h = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var v: UInt64 = 0
        Scanner(string: h).scanHexInt64(&v)
        let r, g, b: Double
        switch h.count {
        case 6: r = Double((v >> 16) & 0xFF) / 255; g = Double((v >> 8) & 0xFF) / 255; b = Double(v & 0xFF) / 255
        case 8: r = Double((v >> 24) & 0xFF) / 255; g = Double((v >> 16) & 0xFF) / 255; b = Double((v >> 8) & 0xFF) / 255
        default: r = 0.5; g = 0.5; b = 0.5
        }
        self.init(.sRGB, red: r, green: g, blue: b, opacity: 1)
    }
}
